import{_ as n,o as i,c as h,a3 as o}from"./chunks/framework.DX_KL3e0.js";const a="/help/screenshots/tickets/tong-quan.png",k=JSON.parse('{"title":"Ticket Hỗ Trợ","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/tickets.md","filePath":"chuc-nang/tickets.md","lastUpdated":1782639524000}'),c={name:"chuc-nang/tickets.md"};function g(e,t,r,l,s,u){return i(),h("div",null,[...t[0]||(t[0]=[o('<h1 id="ticket-ho-tro" tabindex="-1">Ticket Hỗ Trợ <a class="header-anchor" href="#ticket-ho-tro" aria-label="Permalink to &quot;Ticket Hỗ Trợ&quot;">​</a></h1><p>Module <strong>Ticket Hỗ Trợ</strong> là kênh xử lý yêu cầu nội bộ: nhân viên gửi ticket khi cần hỗ trợ, bộ phận liên quan tiếp nhận, xử lý và phản hồi. Mọi trao đổi, tệp đính kèm và thay đổi trạng thái đều được lưu vết.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tickets</code> (menu <strong>Ticket Hỗ Trợ</strong> ở nhóm <em>Hoạt Động</em>).</li><li><strong>Ai dùng được:</strong> Mọi người dùng. Hệ thống tự điều hướng theo vai trò: <ul><li>Super Admin / Admin → giao diện quản trị <code>/tickets/admin</code>.</li><li>Người dùng / Quản lý → giao diện cá nhân <code>/tickets/user</code>.</li></ul></li><li><strong>Trạng thái ticket:</strong> Đã gửi → Đang xử lý → Đã hoàn thành → Đóng (hoặc Từ chối).</li></ul></div><h2 id="giao-dien-nguoi-dung-—-ticket-cua-toi" tabindex="-1">Giao diện người dùng — &quot;Ticket Của Tôi&quot; <a class="header-anchor" href="#giao-dien-nguoi-dung-—-ticket-cua-toi" aria-label="Permalink to &quot;Giao diện người dùng — &quot;Ticket Của Tôi&quot;&quot;">​</a></h2><p><img src="'+a+'" alt="Trang Ticket Hỗ trợ"></p><p>Màn hình cá nhân có <strong>ba tab</strong>:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Hiển thị</th></tr></thead><tbody><tr><td><strong>Ticket được giao cho tôi</strong></td><td>Ticket bạn là người xử lý.</td></tr><tr><td><strong>Đã gửi</strong></td><td>Ticket do bạn tạo.</td></tr><tr><td><strong>Đang theo dõi</strong></td><td>Ticket bạn đang theo dõi (follow).</td></tr></tbody></table><p>Trên mỗi tab có <strong>ô tìm kiếm</strong> (theo tiêu đề hoặc mã ticket) và <strong>bộ lọc trạng thái</strong>.</p><h2 id="giao-dien-quan-tri" tabindex="-1">Giao diện quản trị <a class="header-anchor" href="#giao-dien-quan-tri" aria-label="Permalink to &quot;Giao diện quản trị&quot;">​</a></h2><p>Super Admin/Admin có thêm bảng điều khiển: thẻ thống kê, bộ lọc nâng cao, bảng/bảng Kanban, thao tác hàng loạt và phân công xử lý.</p><h2 id="thao-tac-chinh" tabindex="-1">Thao tác chính <a class="header-anchor" href="#thao-tac-chinh" aria-label="Permalink to &quot;Thao tác chính&quot;">​</a></h2><h3 id="tao-ticket-moi" tabindex="-1">Tạo ticket mới <a class="header-anchor" href="#tao-ticket-moi" aria-label="Permalink to &quot;Tạo ticket mới&quot;">​</a></h3><ol><li>Nhấn nút <strong>Tạo ticket</strong> ở góc phải.</li><li>Trong cửa sổ <strong>Tạo Ticket Mới</strong>, điền: <ul><li><strong>Tiêu Đề</strong> <em>(bắt buộc)</em> — mô tả ngắn gọn vấn đề.</li><li><strong>Loại Yêu Cầu</strong> và <strong>Danh Mục</strong> / <strong>Danh Mục Chi Tiết</strong> <em>(bắt buộc)</em> — phân loại ticket.</li><li><strong>Mô Tả Chi Tiết</strong> — trình bày đầy đủ vấn đề.</li><li><strong>Độ Ưu Tiên</strong> — Thấp / Trung bình / Cao.</li><li><strong>Đơn Vị Xử Lý</strong> và <strong>Người Được Giao</strong> — chọn bằng cách tìm theo tên, chức vụ, phòng ban.</li><li><strong>Tệp đính kèm</strong> (nếu cần) — mỗi tệp tối đa <strong>10MB</strong>.</li></ul></li><li>Một số danh mục có thêm <strong>trường tùy chỉnh</strong>; trường có dấu <code>*</code> là bắt buộc.</li><li>Nhấn nút tạo để gửi ticket.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Chọn đúng <strong>Danh Mục</strong> và <strong>Đơn Vị Xử Lý</strong> giúp ticket đến đúng người, được xử lý nhanh hơn.</p></div><h3 id="theo-doi-xu-ly-ticket" tabindex="-1">Theo dõi &amp; xử lý ticket <a class="header-anchor" href="#theo-doi-xu-ly-ticket" aria-label="Permalink to &quot;Theo dõi &amp; xử lý ticket&quot;">​</a></h3><ol><li>Nhấn vào một ticket để mở <strong>bảng chi tiết</strong>.</li><li>Bảng chi tiết có các tab: <ul><li><strong>Tổng quan</strong> — thông tin chính, trạng thái, người được giao.</li><li><strong>Tệp đính kèm</strong> — tải lên/xem tài liệu liên quan.</li><li><strong>Hoạt động</strong> — nhật ký thay đổi.</li><li><strong>Bình luận</strong> — trao đổi trong ticket.</li><li><strong>Người theo dõi</strong> — quản lý danh sách người nhận thông báo.</li></ul></li><li>Thanh trạng thái hiển thị tiến trình: <strong>Đã gửi → Đang xử lý → Đã hoàn thành → Đóng</strong>.</li></ol><h3 id="binh-luan" tabindex="-1">Bình luận <a class="header-anchor" href="#binh-luan" aria-label="Permalink to &quot;Bình luận&quot;">​</a></h3><ol><li>Mở tab <strong>Bình luận</strong> trong chi tiết ticket.</li><li>Nhập nội dung; có thể nhắc tên (mention) người khác để họ nhận thông báo.</li><li>Gửi bình luận — nội dung được lưu vào nhật ký ticket.</li></ol><h3 id="nguoi-theo-doi-watchers" tabindex="-1">Người theo dõi (Watchers) <a class="header-anchor" href="#nguoi-theo-doi-watchers" aria-label="Permalink to &quot;Người theo dõi (Watchers)&quot;">​</a></h3><ol><li>Mở tab <strong>Người theo dõi</strong>.</li><li>Thêm người cần nhận cập nhật về ticket; có thể cấu hình thông báo cho từng người.</li><li>Người dùng cũng có thể tự <strong>theo dõi</strong> ticket để nó xuất hiện ở tab <em>Đang theo dõi</em>.</li></ol><h3 id="cong-viec-lien-quan-đen-ticket" tabindex="-1">Công việc liên quan đến ticket <a class="header-anchor" href="#cong-viec-lien-quan-đen-ticket" aria-label="Permalink to &quot;Công việc liên quan đến ticket&quot;">​</a></h3><p>Trong chi tiết ticket, panel <strong>Công Việc Liên Quan</strong> cho phép gắn các công việc (Tasks) phục vụ xử lý ticket. Người được giao xử lý ticket có thể bấm <strong>+ Tạo công việc</strong> để mở nhanh form tạo task — task tạo từ đây tự liên kết về ticket gốc.</p><div class="tip custom-block"><p class="custom-block-title">Theo dõi tiến độ chung</p><p>Khi ticket có công việc liên kết, bạn theo dõi tiến độ ngay trên panel: số task đã xong / tổng số. Mở từng task để cập nhật trạng thái — ticket không bị tự đóng khi còn task chưa hoàn thành.</p></div><h3 id="trang-thai-tu-đong" tabindex="-1">Trạng thái &amp; tự đóng <a class="header-anchor" href="#trang-thai-tu-đong" aria-label="Permalink to &quot;Trạng thái &amp; tự đóng&quot;">​</a></h3><ul><li>Khi ticket được đánh dấu <strong>Đã hoàn thành</strong>, hệ thống hiển thị thông báo <em>&quot;Ticket đã hoàn thành · Tự đóng sau 3 ngày&quot;</em> và sẽ <strong>tự đóng</strong> sau 3 ngày nếu không có hoạt động mới.</li><li>Khi ticket bị <strong>Từ chối</strong>, lý do từ chối được ghi lại và ticket cũng <strong>tự đóng sau 3 ngày</strong>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Nếu vấn đề chưa được giải quyết, hãy thêm bình luận trước khi ticket tự đóng, hoặc tạo ticket mới tham chiếu ticket cũ.</p></div><h3 id="luu-tru-tu-đong" tabindex="-1">Lưu trữ tự động <a class="header-anchor" href="#luu-tru-tu-đong" aria-label="Permalink to &quot;Lưu trữ tự động&quot;">​</a></h3><p>Sau khi ticket đã ở trạng thái cuối (Hoàn thành / Đã giải quyết / Từ chối / Đã đóng) quá <strong>7 ngày</strong>, hệ thống <strong>tự ẩn</strong> khỏi danh sách chính (đánh dấu <em>lưu trữ</em>). Việc này giữ giao diện gọn — danh sách chính chỉ hiển thị ticket còn cần chú ý.</p><div class="info custom-block"><p class="custom-block-title">Vẫn xem lại được</p><p>Ticket đã lưu trữ không bị xóa — vẫn nằm trong dữ liệu lịch sử, vẫn tìm được qua thanh tìm kiếm và báo cáo. Khi cần mở lại, liên hệ Quản trị viên.</p></div><h2 id="cau-hinh-lien-quan" tabindex="-1">Cấu hình liên quan <a class="header-anchor" href="#cau-hinh-lien-quan" aria-label="Permalink to &quot;Cấu hình liên quan&quot;">​</a></h2><p>Người quản trị có thể quản lý loại yêu cầu, danh mục và danh mục chi tiết tại <a href="/help/quan-tri/cau-hinh-ticket-nang-cao.html">Cấu Hình Ticket Nâng Cao</a>.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Vì sao tôi vào <code>/tickets</code> lại thấy giao diện khác đồng nghiệp?</strong> Hệ thống điều hướng theo vai trò: quản trị viên thấy bảng điều khiển quản trị, người dùng thường thấy &quot;Ticket Của Tôi&quot;.</p><p><strong>Làm sao biết ticket của tôi được xử lý đến đâu?</strong> Mở ticket và xem thanh trạng thái cùng tab <strong>Hoạt động</strong>. Nếu đang theo dõi, bạn sẽ nhận thông báo khi có cập nhật.</p><p><strong>Ticket đã hoàn thành nhưng vấn đề chưa xong?</strong> Thêm bình luận trong vòng 3 ngày để ticket không tự đóng, hoặc liên hệ người được giao xử lý.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/cong-viec.html">Công Việc</a> · <a href="/help/chuc-nang/dashboard.html">Dashboard</a></p>',37)])])}const m=n(c,[["render",g]]);export{k as __pageData,m as default};
